struct vdi_fixture{uint16_t opcode;int calls;};struct line_fixture{int calls;};struct aes_fixture{int calls;};
static int32_t vd(void*o,uint16_t op,const int16_t*i,uint16_t ni,const int16_t*p,uint16_t np,int16_t*out,uint16_t oc,uint16_t*no,int16_t*po,uint16_t pc,uint16_t*npo){struct vdi_fixture*f=o;(void)i;(void)ni;(void)p;(void)np;(void)oc;(void)pc;f->opcode=op;f->calls++;out[0]=42;po[0]=320;po[1]=200;*no=1;*npo=2;return 0;}static int line(void*o,int16_t a,int16_t b,int16_t c,int16_t d,uint16_t e,uint16_t f){struct line_fixture*x=o;(void)a;(void)b;(void)c;(void)d;(void)e;(void)f;x->calls++;return 0;}static int32_t aes(void*o,uint16_t op,const int16_t*i,uint16_t ni,int16_t*out,uint16_t oc,uint16_t*no,const uint32_t*ai,uint16_t nai,uint32_t*ao,uint16_t oac,uint16_t*nao){struct aes_fixture*f=o;(void)op;(void)i;(void)ni;(void)ai;(void)nai;(void)ao;(void)oac;(void)nao;assert(oc);f->calls++;out[0]=77;*no=1;return 0;}static void w16(uint8_t*m,uint32_t a,uint16_t v){m[a]=(uint8_t)(v>>8);m[a+1]=(uint8_t)v;}static void w32(uint8_t*m,uint32_t a,uint32_t v){w16(m,a,(uint16_t)(v>>16));w16(m,a+2,(uint16_t)v);}static void pb(uint8_t*m,uint16_t op){w32(m,0x100,0x140);w32(m,0x104,0x180);w32(m,0x108,0x1c0);w32(m,0x10c,0x200);w32(m,0x110,0x280);w16(m,0x140,op);w16(m,0x142,0);w16(m,0x146,0);}static void apb(uint8_t*m,uint16_t op,uint16_t ni,uint16_t no,uint16_t nai){w32(m,0x300,0x340);w32(m,0x304,0x360);w32(m,0x308,0x380);w32(m,0x30c,0x3c0);w32(m,0x310,0x400);w32(m,0x314,0x440);w16(m,0x340,op);w16(m,0x342,ni);w16(m,0x344,no);w16(m,0x346,nai);w16(m,0x348,0);}
int main(void){struct amtari_context c={0};struct vdi_fixture v={0};struct line_fixture l={0};struct aes_fixture a={0};int16_t out[64]={0},po[16]={0},p[6]={10,20,30,40,50,60},in[2]={7,9};uint32_t ai[1]={0x12345678},ao[2]={0};uint16_t no=0,npo=0,x;uint8_t mem[2048];assert(!amtari_init(&c));assert(!strcmp(amtari_version(),AMTARI_VERSION));assert(!amtari_vdi_configure(&c,640,400,16));assert(!amtari_vdi_dispatch(&c,1,0,0,0,0,out,64,&no,po,16,&npo));assert(no==45&&npo==12&&out[0]==639&&out[13]==16);assert(!amtari_vdi_line_bind(&c,line,&l));assert(!amtari_vdi_dispatch(&c,6,0,0,p,6,out,64,&no,po,16,&npo));assert(l.calls==2);assert(!amtari_vdi_bind(&c,vd,&v));assert(!amtari_vdi_dispatch(&c,100,0,0,0,0,out,64,&no,po,16,&npo));assert(v.calls==1);assert(!amtari_aes_set_application_name(&c,"AMTARI"));assert(!amtari_aes_dispatch(&c,10,0,0,out,64,&no,0,0,ao,2,&npo));assert(out[0]==1);assert(!amtari_aes_dispatch(&c,19,0,0,out,64,&no,0,0,ao,2,&npo));assert(!amtari_aes_bind(&c,aes,&a));assert(!amtari_aes_dispatch(&c,99,in,2,out,64,&no,ai,1,ao,2,&npo));assert(a.calls==1&&out[0]==77);
memset(mem,0,sizeof(mem));assert(!amtari_guest_memory_bind(&c,mem,sizeof(mem)));w16(mem,0x20,0x4e42);pb(mem,100);c.cpu.pc=0x20;c.cpu.d[0]=0x73;c.cpu.d[1]=0x100;assert(amtari_exec_step(&c)==AMTARI_EXEC_RUNNING);assert(!amtari_guest_read16(&c,0x200,&x)&&x==42);memset(mem,0,sizeof(mem));w16(mem,0x20,0x4e42);pb(mem,1);c.cpu.pc=0x20;c.cpu.d[0]=0x73;c.cpu.d[1]=0x100;assert(amtari_exec_step(&c)==AMTARI_EXEC_RUNNING);assert(!amtari_guest_read16(&c,0x14c,&x)&&x==2);
/* M3.14: appl_init then appl_write(own apid,16,message) through AES TRAP #2. */
memset(mem,0,sizeof(mem));w16(mem,0x20,0x4e42);apb(mem,10,0,1,0);c.cpu.pc=0x20;c.cpu.d[0]=0xc8;c.cpu.d[1]=0x300;assert(amtari_exec_step(&c)==AMTARI_EXEC_RUNNING);assert(!amtari_guest_read16(&c,0x3c0,&x));assert(x==2);w16(mem,0x480,20);w16(mem,0x482,2);w16(mem,0x484,0);w16(mem,0x486,10);w16(mem,0x488,20);w16(mem,0x48a,30);w16(mem,0x48c,40);w16(mem,0x48e,50);apb(mem,12,2,1,1);w16(mem,0x380,2);w16(mem,0x382,16);w32(mem,0x400,0x480);w16(mem,0x20,0x4e42);c.cpu.pc=0x20;c.cpu.d[0]=0xc8;c.cpu.d[1]=0x300;assert(amtari_exec_step(&c)==AMTARI_EXEC_RUNNING);assert(!amtari_guest_read16(&c,0x3c0,&x)&&x==1);assert(c.aes.message_pending&&c.aes.message_length==16&&c.aes.message_destination==2);assert(c.aes.message[0]==0&&c.aes.message[1]==20&&c.aes.message[2]==0&&c.aes.message[3]==2);/* occupied mailbox and invalid destination return AES false */w16(mem,0x20,0x4e42);c.cpu.pc=0x20;assert(amtari_exec_step(&c)==AMTARI_EXEC_RUNNING);assert(!amtari_guest_read16(&c,0x3c0,&x)&&x==0);c.aes.message_pending=0;w16(mem,0x380,99);w16(mem,0x20,0x4e42);c.cpu.pc=0x20;assert(amtari_exec_step(&c)==AMTARI_EXEC_RUNNING);assert(!amtari_guest_read16(&c,0x3c0,&x)&&x==0);return 0;}
